pub tracked struct ContextGhost<DT: Dispatch> {
    pub batch_perms: Option<PointsTo<PendingOperation<DT>>>,

    pub slots: FlatCombiner::slots,

    pub update: Option<UnboundedLog::local_updates<DT>>
